	db	41h,4Bh,30h,30h,35h,32h,2Eh,31h	; 0064  AK0052.1
	db	33h,39h,55h,31h,00h,00h,01h,00h	; 006C  39U1....
	db	00h,2Fh,30h,00h,01h,00h,0FFh,40h	; 0074  ./0....@
