isr_rst55:
	PUSH	PSW
	MVI	A,0Bh
	SIM
	EI
	PUSH	B
	PUSH	D
	PUSH	H
	IN	sw_port_c
	ANI	20h
	JZ	isr_rst55_br3
	MVI	A,01h
	STA	in_isr_flag
	MVI	A,4Eh
	STA	isr_mailbox
	LDA	rx_handler_sel
	CPI	01h
	JZ	isr_rst55_br1
	CALL	rx_handler_a
	JMP	isr_rst55_br2
isr_rst55_br1:
	CALL	rx_handler_b
	LDA	uart_rx_byte
	MOV	B,A
	LDA	0A054h
	XRA	B
	STA	0A054h
isr_rst55_br2:
	SUB	A
	STA	in_isr_flag
isr_rst55_loop1:
	POP	H
	POP	D
	POP	B
	DI
	MVI	A,0Ah
	SIM
	POP	PSW
	EI
	RET
isr_rst55_br3:
	CALL	rx_handler_c
	JMP	isr_rst55_loop1
isr_rst75:
	DI
	PUSH	PSW
	PUSH	H
	MVI	A,0C0h
	SIM
	LDA	watchdog_count
	CPI	00h
	JZ	isr_rst75_br1
	CPI	01h
	JZ	fatal_or_init
	DCR	A
	STA	watchdog_count
isr_rst75_br1:
	CALL	hw_status_sample
	LXI	H,clock_cmd_mailbox
	MOV	A,M
	INX	H
	CPI	00h
	JNZ	isr_rst75_br4
	IN	clock_cmd
	ANI	0F4h
	CMP	M
	JZ	isr_rst75_br2
	MOV	M,A
	CPI	0F4h
	JZ	isr_rst75_br3
	INX	H
	MVI	M,0C9h
	DCX	H
isr_rst75_br2:
	INX	H
	MOV	A,M
	CPI	00h
	JZ	isr_rst75_br4
	DCR	M
	JNZ	isr_rst75_br4
isr_rst75_br3:
	MVI	A,01h
	STA	clock_cmd_mailbox
isr_rst75_br4:
	LDA	attr_active
	CPI	00h
	JZ	isr_rst75_br6
	LHLD	effect_duration
	MOV	A,H
	ORA	L
	JZ	isr_rst75_br5
	DCX	H
	SHLD	effect_duration
isr_rst75_br5:
	LHLD	effect_duration2
	MOV	A,H
	ORA	L
	JZ	isr_rst75_br6
	DCX	H
	SHLD	effect_duration2
isr_rst75_br6:
	LDA	tick_wait_flags
	CPI	00h
	JZ	isr_rst75_br8
	CPI	81h
	JNZ	isr_rst75_br7
	LDA	0A01Ah
	OUT	disp1_port_c
	MVI	A,01h
	STA	tick_wait_flags
	JMP	isr_rst75_br8
isr_rst75_br7:
	LHLD	tick_wait_count
	DCX	H
	SHLD	tick_wait_count
	MOV	A,H
	ORA	L
	JNZ	isr_rst75_br8
	SUB	A
	STA	tick_wait_flags
	IN	xram_page
	CPI	0FFh
	JZ	isr_rst75_br8
	MVI	A,2Bh
	OUT	disp1_port_c
isr_rst75_br8:
	MVI	A,40h
	SIM
	POP	H
	POP	PSW
	EI
	RET
fatal_or_init:
	DI
init_stack:
	LXI	SP,0A0F3h
	SUB	A
	STA	in_isr_flag
	CALL	sod_pulse
	CALL	init_display_ifaces
	IN	sw_port_c
	ANI	20h
	JNZ	init_stack_br1
	SUB	A
	STA	rx_handler_sel
	MVI	A,20h
	STA	status_flags_b
	STA	0A080h
	MVI	A,0A0h
	STA	0A07Dh
init_stack_br1:
	LDA	rx_handler_sel
	CPI	00h
	CNZ	init_clear_state
	MVI	A,1Ah
	SIM
	EI
	IN	sw_port_c
	ANI	20h
	JZ	main_loop
	MVI	A,06h
	STA	clock_cmd_mailbox
	LDA	refresh_mode
	CPI	00h
	JNZ	init_stack_loop3
init_stack_loop1:
	CALL	render_task
	JMP	init_stack_loop1
init_stack_loop2:
	CALL	render_task
init_stack_loop3:
	CALL	attr_age
	CALL	clock_service
poll_rx_state:
	MVI	C,4Eh
	LXI	H,isr_mailbox
	DI
	MOV	B,M
	MOV	M,C
	EI
	MOV	A,B
	CPI	4Ah
	JZ	init_stack_loop2
	JMP	init_stack_loop3
main_loop:
	CALL	attr_age
	LDA	status_flags_b
	ANI	0C0h
	CPI	40h
	JNZ	main_loop
	LDA	status_flags_a
	ANI	01h
	JNZ	main_loop
main_loop_replay:
	LXI	H,state_vt
	LDA	rx_c_stage_len
	MOV	B,A
main_loop_replay_loop1:
	PUSH	H
	PUSH	B
	MVI	B,61h
	MVI	C,03h
	MOV	A,M
	LHLD	rx_write_ptr
	CALL	rx_a_store_byte
	POP	B
	POP	H
	INX	H
	DCR	B
	JNZ	main_loop_replay_loop1
	LDA	status_flags_b
	ANI	1Fh
	ORI	20h
	STA	status_flags_b
	CALL	render_pass_paged
	JMP	main_loop
init_display_ifaces:
	SUB	A
	OUT	disp0_timer_lo
	MVI	A,46h
	OUT	disp0_timer_hi
	MVI	A,0CFh
	OUT	disp0_cmd
	MVI	A,80h
	OUT	disp0_port_a
	OUT	disp0_port_b
	NOP
	NOP
	NOP
	SUB	A
	OUT	disp0_port_a
	OUT	disp0_port_b
	OUT	disp0_port_c
	OUT	sw_cmd
	IN	xram_page
	CPI	0FFh
	JZ	init_check_mode_switch
	SUB	A
	OUT	disp1_timer_lo
	MVI	A,46h
	OUT	disp1_timer_hi
	MVI	A,0CFh
	OUT	disp1_cmd
	MVI	A,03h
	OUT	disp1_port_c
	SUB	A
	OUT	disp1_port_b
	MVI	A,0FFh
	OUT	disp1_port_a
	MVI	A,0E0h
	OUT	xram_page
init_check_mode_switch:
	IN	sw_port_c
	ANI	20h
	JNZ	init_alt_path
	MVI	A,14h
	OUT	sw_timer_lo
	MVI	A,40h
	OUT	sw_timer_hi
	MVI	A,0C0h
	OUT	sw_cmd
init_uart:
	SUB	A
	OUT	uart_ctrl
	OUT	uart_ctrl
	OUT	uart_ctrl
	MVI	A,40h
	OUT	uart_ctrl
	MVI	A,7Eh
	OUT	uart_ctrl
	STA	uart_mode_word
	MVI	A,37h
	OUT	uart_ctrl
clear_ram_f0:
	LXI	H,0A000h
	MVI	B,0F0h
	SUB	A
clear_ram_f0_loop1:
	MOV	M,A
	INX	H
	DCR	B
	JNZ	clear_ram_f0_loop1
	JMP	init_uart_from_switches_br2
init_alt_path:
	SUB	A
clear_ram_80:
	LXI	H,0A000h
	MVI	B,80h
clear_ram_80_loop1:
	MOV	M,A
	INX	H
	DCR	B
	JNZ	clear_ram_80_loop1
select_baud_rate:
	IN	sw_port_b
	ANI	0E0h
	CPI	00h
	JZ	baud_9600_br5
	CPI	20h
	JZ	baud_9600_br4
	CPI	40h
	JZ	baud_9600_br3
	CPI	60h
	JZ	baud_9600_br2
	CPI	80h
	JZ	baud_9600_br1
baud_9600:
	MVI	A,14h
	STA	timer_preload_lo
	MVI	A,40h
	STA	timer_preload_hi
	JMP	baud_9600_br6
baud_9600_br1:
	MVI	A,28h
	STA	timer_preload_lo
	MVI	A,40h
	STA	timer_preload_hi
	JMP	baud_9600_br6
baud_9600_br2:
	MVI	A,50h
	STA	timer_preload_lo
	MVI	A,40h
	STA	timer_preload_hi
	JMP	baud_9600_br6
baud_9600_br3:
	MVI	A,0A0h
	STA	timer_preload_lo
	MVI	A,40h
	STA	timer_preload_hi
	JMP	baud_9600_br6
baud_9600_br4:
	MVI	A,40h
	STA	timer_preload_lo
	MVI	A,41h
	STA	timer_preload_hi
	JMP	baud_9600_br6
baud_9600_br5:
	MVI	A,80h
	STA	timer_preload_lo
	MVI	A,42h
	STA	timer_preload_hi
baud_9600_br6:
	LDA	timer_preload_lo
	OUT	sw_timer_lo
	LDA	timer_preload_hi
	OUT	sw_timer_hi
	MVI	A,0C0h
